import{_ as a,o as s,c as o,a2 as n}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"能力值详解","description":"","frontmatter":{},"headers":[],"relativePath":"guide/characters-stats.md","filePath":"guide/characters-stats.md","lastUpdated":1787389693000}'),r={name:"guide/characters-stats.md"};function e(l,t,i,d,p,g){return s(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="能力值详解" tabindex="-1">能力值详解 <a class="header-anchor" href="#能力值详解" aria-label="Permalink to &quot;能力值详解&quot;">​</a></h1><p>角色各方面的能力值，包括：<strong>生命值、魔法值、爆发能量、行动速度（行动系数）、攻击力、物理护甲（物理伤害减免）、魔法抗性、加速系数、闪避率、暴击率、暴击伤害、物理穿透、魔法穿透、冷却缩减、生命回复、魔法回复</strong>。</p><h2 id="基础能力值与额外能力值" tabindex="-1">基础能力值与额外能力值 <a class="header-anchor" href="#基础能力值与额外能力值" aria-label="Permalink to &quot;基础能力值与额外能力值&quot;">​</a></h2><ul><li><strong>基础能力值</strong>：角色基于<strong>初始属性</strong>、<strong>核心属性</strong>、<strong>等级</strong>等因素计算的</li><li><strong>额外能力值</strong>：通过<strong>装备</strong>、<strong>技能</strong>等方式获得的属性加成</li></ul><blockquote><p>所有百分比加成的能力值乘算，都基于角色的<strong>基础能力值</strong>计算。</p></blockquote><h2 id="运算规则" tabindex="-1">运算规则 <a class="header-anchor" href="#运算规则" aria-label="Permalink to &quot;运算规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力值类型</th><th>是否具备基础值</th><th>加成方式</th></tr></thead><tbody><tr><td>生命值 / 魔法值 / 爆发能量 / 行动速度 / 攻击力 / 物理护甲</td><td>✅ 有基础能力值</td><td>百分比乘算基于基础能力值</td></tr><tr><td>魔法抗性 / 加速系数 / 闪避率 / 暴击率 / 暴击伤害 / 物理穿透 / 魔法穿透 / 冷却缩减</td><td>❌ 无基础能力值</td><td>可以接受<strong>百分比乘算</strong>，也可以接受<strong>百分比加算</strong></td></tr><tr><td>生命回复 / 魔法回复</td><td>❌ 无基础能力值</td><td><strong>只能接受加算</strong>；或由其<strong>初始生命回复 / 初始魔法回复</strong>接受乘算</td></tr><tr><td>攻击距离 / 移动距离</td><td>✅ 分基础/额外</td><td>只有在<strong>战棋地图</strong>上才会应用，<strong>仅接受加算</strong></td></tr></tbody></table><h2 id="初始能力值" tabindex="-1">初始能力值 <a class="header-anchor" href="#初始能力值" aria-label="Permalink to &quot;初始能力值&quot;">​</a></h2><p><strong>定义</strong>：角色 1 级时自带的能力值。</p><p>这个很重要——<strong>具备初始能力值的能力值类型，其数值可能影响每次提升等级时，一同提升的能力值</strong>。</p><p>角色存在以下初始能力值：</p><table tabindex="0"><thead><tr><th>初始能力值</th><th>影响</th></tr></thead><tbody><tr><td>初始生命值</td><td>影响基础最大生命值成长</td></tr><tr><td>初始魔法值</td><td>影响基础最大魔法值成长</td></tr><tr><td>初始行动速度</td><td>直接决定开局行动系数</td></tr><tr><td>初始攻击力</td><td>影响基础攻击力成长</td></tr><tr><td>初始物理护甲</td><td>直接参与物理伤害减免</td></tr><tr><td>初始生命回复</td><td>生命回复乘算的基准</td></tr><tr><td>初始魔法回复</td><td>魔法回复乘算的基准</td></tr></tbody></table><hr><h2 id="最大生命值" tabindex="-1">最大生命值 <a class="header-anchor" href="#最大生命值" aria-label="Permalink to &quot;最大生命值&quot;">​</a></h2><p>角色的基础最大生命值基于以下公式计算：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基础最大生命值 = 初始生命值 + (等级 - 1) * (17 + 0.68 * 初始生命值) + 基础力量 * 9</span></span>
<span class="line"><span>最大生命值 = 基础最大生命值 + (额外力量 * 9) + 额外生命值加成</span></span></code></pre></div><h2 id="最大魔法值" tabindex="-1">最大魔法值 <a class="header-anchor" href="#最大魔法值" aria-label="Permalink to &quot;最大魔法值&quot;">​</a></h2><p>角色的基础最大魔法值基于以下公式计算：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基础最大魔法值 = 初始魔法值 + (等级 - 1) * (1.5 + 0.14 * 初始魔法值) + 基础智力 * 8</span></span>
<span class="line"><span>最大魔法值 = 基础最大魔法值 + (额外智力 * 8) + 额外魔法值加成</span></span></code></pre></div><h2 id="爆发能量" tabindex="-1">爆发能量 <a class="header-anchor" href="#爆发能量" aria-label="Permalink to &quot;爆发能量&quot;">​</a></h2><p>角色释放<strong>战技</strong>和<strong>爆发技</strong>所需的能力值。</p><ul><li>爆发能量最大值为 <strong>200</strong> 点</li><li>角色造成、受到伤害都会获得<strong>少量</strong>的爆发能量</li><li>我们统一能量值的术语为<strong>获得</strong>，而不是<strong>回复</strong></li></ul><h2 id="行动速度" tabindex="-1">行动速度 <a class="header-anchor" href="#行动速度" aria-label="Permalink to &quot;行动速度&quot;">​</a></h2><p>角色的行动速度在<strong>战斗开局</strong>时起关键作用。在战斗过程中，行动速度会按公式转化为角色的<strong>行动系数</strong>，行动系数用于<strong>减少硬直时间</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>行动系数 = 行动速度 / 1500 * 100%（保留两位小数）</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">示例</p><p>290 速度 → 行动系数 = 290 / 1500 * 100% = 19.33% 当硬直时间为 5 时 → 实际硬直时间 = 5 * (1 - 19.33%) = <strong>4.03</strong></p></div><blockquote><p>注：行动系数最大为 <strong>90%</strong>，即当角色行动速度达到 <strong>1350</strong> 时为最大速度。详见 <a href="/guide/action-queue.html">行动顺序表</a>。</p></blockquote><h2 id="攻击力" tabindex="-1">攻击力 <a class="header-anchor" href="#攻击力" aria-label="Permalink to &quot;攻击力&quot;">​</a></h2><p>角色的基础攻击力由<strong>初始攻击力及其成长</strong>和<strong>基础核心属性</strong>相加而成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基础攻击力 = 初始攻击力 + (等级 - 1) * (0.95 + 0.045 * 初始攻击力) + 基础核心属性</span></span>
<span class="line"><span>总攻击力 = 基础攻击力 + 额外攻击力加成</span></span></code></pre></div><h2 id="物理护甲和物理穿透" tabindex="-1">物理护甲和物理穿透 <a class="header-anchor" href="#物理护甲和物理穿透" aria-label="Permalink to &quot;物理护甲和物理穿透&quot;">​</a></h2><p>在物理伤害计算中，物理护甲最终会转换成<strong>物理伤害减免</strong>参与伤害计算：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>物理伤害减免 = 物理护甲 /（物理护甲 + 240）* 100%（保留两位小数）</span></span></code></pre></div><p><strong>物理穿透</strong>用于削减目标角色的物理护甲。例如角色 1 的物理穿透为 30%，角色 2 的物理护甲为 60：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(1 - 0.3) * 60 = 42（角色 2 的物理护甲最终取 42）</span></span></code></pre></div><p>详见 <a href="/guide/damage.html">伤害计算 - 物理伤害</a>。</p><h2 id="魔法抗性和魔法穿透" tabindex="-1">魔法抗性和魔法穿透 <a class="header-anchor" href="#魔法抗性和魔法穿透" aria-label="Permalink to &quot;魔法抗性和魔法穿透&quot;">​</a></h2><p>魔法抗性将<strong>直接参与</strong>到伤害计算中（与物理护甲 → 物理伤害减免的转换同理），魔法穿透直接作用于魔法抗性。因没有魔法护甲，所以魔法穿透将直接作用于魔法抗性。</p><blockquote><p>特别地，魔法伤害具有属性（星痕、光、影、元素等），角色的属性或技能的伤害属性会应用<strong>不同</strong>的魔法抗性，但魔法穿透为<strong>共用属性</strong>。详见 <a href="/guide/damage.html">伤害计算 - 魔法伤害</a>。</p></blockquote><h2 id="加速系数" tabindex="-1">加速系数 <a class="header-anchor" href="#加速系数" aria-label="Permalink to &quot;加速系数&quot;">​</a></h2><p>这涉及魔法理论。如果角色想要释放魔法技能，角色必须先经过一段时间的<strong>吟唱</strong>（或说施法、蓄力或引导），在本游戏的系统中标准称呼为<strong>吟唱时间</strong>。</p><ul><li>在这个过程中，角色<strong>无法进行任何操作</strong>，除了等待吟唱时间结束、被敌人打断，别无其他选择</li><li>也<strong>不能通过预释放爆发技来取消吟唱</strong></li></ul><p>对行动顺序表作一些补充：</p><ol><li>当角色在回合中确定吟唱魔法时，<strong>吟唱时间会替代硬直时间</strong>来使角色插入行动顺序表</li><li>但此时角色<strong>不适用行动系数</strong>来削减这个硬直时间，必须要用专门的<strong>加速系数</strong>来削减这个硬直时间</li></ol><p>总而言之，<strong>加速系数是用来削减吟唱时间的</strong>。数值越大，角色将能更快释放出魔法。并且魔法技能也会有硬直时间，在角色释放魔法以后，要正常走行动顺序表中的硬直时间计算逻辑。</p><h2 id="闪避率" tabindex="-1">闪避率 <a class="header-anchor" href="#闪避率" aria-label="Permalink to &quot;闪避率&quot;">​</a></h2><p>闪避率通常<strong>仅在成为普通攻击的目标时</strong>才有效。</p><p>这个指标将用于进行<strong>闪避检定</strong>，原理为投掷一个 100 以内的随机数，小于闪避率的值则视为角色<strong>闪避成功</strong>，将无法受到该普通攻击的伤害。</p><h2 id="暴击率和暴击伤害" tabindex="-1">暴击率和暴击伤害 <a class="header-anchor" href="#暴击率和暴击伤害" aria-label="Permalink to &quot;暴击率和暴击伤害&quot;">​</a></h2><p>这是两个令人兴奋的能力值。<strong>任何伤害</strong>都会在计算减伤之后，进行<strong>暴击检定</strong>，检定原理与闪避类似，当暴击生效时，期望伤害将直接乘以暴击伤害。</p><ul><li>角色拥有 <strong>5%</strong> 初始暴击率</li><li>角色拥有 <strong>125%</strong> 初始暴击伤害</li></ul><h2 id="冷却缩减" tabindex="-1">冷却缩减 <a class="header-anchor" href="#冷却缩减" aria-label="Permalink to &quot;冷却缩减&quot;">​</a></h2><p>冷却缩减可以减少<strong>所有主动技能</strong>（战技、魔法、爆发技）的冷却时间。</p><h2 id="生命回复和魔法回复" tabindex="-1">生命回复和魔法回复 <a class="header-anchor" href="#生命回复和魔法回复" aria-label="Permalink to &quot;生命回复和魔法回复&quot;">​</a></h2><p>生命回复和魔法回复是在<strong>每次时间流逝</strong>时，根据流逝的单位时间，来计算此次回复的数值。</p><div class="tip custom-block"><p class="custom-block-title">示例</p><p>某角色回合结束，时间流逝 1 秒，生命回复为 0.5，则此次回复的数值为 <code>0.5 * 1 = 0.5</code>。</p></div><p>生命回复和魔法回复均有初始值、额外值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总生命回复 = 初始生命回复 + 额外生命回复</span></span>
<span class="line"><span>总魔法回复 = 初始魔法回复 + 额外魔法回复</span></span></code></pre></div><h2 id="生命偷取" tabindex="-1">生命偷取 <a class="header-anchor" href="#生命偷取" aria-label="Permalink to &quot;生命偷取&quot;">​</a></h2><p>简称<strong>吸血</strong>，指角色在造成伤害时，从造成的伤害值中吸取一部分生命值，<strong>转化为生命回复治疗自身</strong>。</p><h2 id="护盾值" tabindex="-1">护盾值 <a class="header-anchor" href="#护盾值" aria-label="Permalink to &quot;护盾值&quot;">​</a></h2><p>护盾是一种<strong>代替生命值结算伤害</strong>的机制，区分<strong>物理护盾</strong>和<strong>魔法护盾</strong>。护盾值通常由<strong>特效</strong>提供。</p><ul><li>角色在护盾生效期间受到伤害时，护盾值会被减少，用来抵挡伤害</li><li>通常情况下，当护盾值减至 <strong>0</strong> 或者受到<strong>比护盾值更大</strong>的伤害时，护盾将被移除并且<strong>溢出伤害由角色生命值承担</strong></li></ul><blockquote><p>特效可以有特殊设计，具体需要看特效的说明。</p></blockquote><h2 id="攻击距离和移动距离" tabindex="-1">攻击距离和移动距离 <a class="header-anchor" href="#攻击距离和移动距离" aria-label="Permalink to &quot;攻击距离和移动距离&quot;">​</a></h2><p>距离在战棋地图上是指两个角色之间的<strong>曼哈顿距离</strong>。</p><ul><li><strong>基础攻击距离</strong>由<strong>武器</strong>提供</li><li><strong>基础移动距离</strong>则由角色的<strong>定位</strong>提供</li></ul><blockquote><p>攻击距离和移动距离只有在战棋地图上才会应用，仅接受加算。</p></blockquote>`,68)])])}const u=a(r,[["render",e]]);export{c as __pageData,u as default};
